<template><section aria-label="合成教学练习与AI反馈"><h3>合成教学练习</h3><p>本地固定集合匹配与模型解释分别处理。这里不填写真实患者资料，教学反馈不代表临床能力或资质。</p><p v-if="!authorized" role="alert">当前会话或明确提交引用无效。</p><template v-else><ClinicalTrainingPractice :key="v.practiceKey" :active="active" :config-revision="configRevision" @select="practiceSelection"/><el-button v-if="initialReferences" :disabled="v.busy" @click="select(initialReferences)">核对传入的本人实际提交</el-button><el-button :disabled="v.busy" @click="configuration">读取当前教学模型配置</el-button><p v-if="!v.feature">尚未取得当前教学模型配置；本地练习仍独立可用。</p><p v-else>当前模型配置：{{v.feature.enabled?'已启用':'未启用'}}；教学反馈范围验证：{{v.feature.validation_status}}。仍需服务端重新核对独立模型许可。</p><p v-if="v.selected">已核对本人实际提交：{{v.selected.clinical_training_submission_id}}</p><label>本次明确教学目标<el-select v-model="v.objective" :disabled="v.busy" aria-label="本次明确教学目标"><el-option v-for="(label,key) in objectives" :key="key" :value="key" :label="label"/></el-select></label><el-button :disabled="!ready||v.busy" @click="generate(false)">请求本次练习教学反馈</el-button><el-button v-if="session.role.value==='super_admin'" :disabled="!configured||!v.selected||!v.objective||v.busy" @click="generate(true)">预览本人练习的教学反馈任务</el-button><el-button :disabled="v.busy" @click="history()">读取当前教学任务目录</el-button><p v-if="v.error" role="alert">{{v.error}}</p><table v-if="v.history"><tbody><tr v-for="row in v.history.items" :key="row.run_id"><td>{{row.run_id}} {{row.status}}</td><td><el-button :disabled="v.busy" @click="openRun(row.run_id)">核对本条任务当前状态</el-button></td></tr></tbody></table><template v-if="v.run"><p aria-label="教学任务当前短状态">任务{{v.run.run_id}}：{{v.run.status}}；{{v.run.receipt_pending?'尚待原在途调用真实回执':v.run.usage?'已有实际独立用量回执':'尚无用量回执'}}。</p><el-button :disabled="v.busy||v.run.parts_state!=='available'" @click="openParts">核对本任务四个完整分件</el-button><el-button v-if="session.role.value==='super_admin'&&['queued','running'].includes(v.run.status)" :disabled="v.busy" @click="cancel">技术停止此任务</el-button><p v-if="v.run.binding===null">仅技术状态可读，不恢复其他学员或失效来源的原件。</p></template><template v-if="v.partsOpen&&v.parts"><el-button @click="closeParts">关闭当前完整反馈</el-button><ClinicalTrainingFindings :metadata="v.run" :parts="v.parts" :active="active" :config-revision="configRevision" @invalidate="clear()"/><template v-if="v.run.status==='succeeded'"><label>人工复核结论<el-select v-model="v.feedbackOutcome" aria-label="人工复核结论"><el-option value="accepted" label="接受教学说明"/><el-option value="rejected" label="不接受教学说明"/><el-option value="modified" label="需人工修改"/></el-select></label><label>本次复核备注<el-input v-model="v.feedbackComment" type="textarea" aria-label="本次复核备注"/></label><el-button :disabled="v.busy||!v.feedbackOutcome" @click="feedback">记录教学说明人工复核</el-button><p v-if="v.feedbackAck" role="status">实际复核回执{{v.feedbackAck.feedback_id}}；原练习计数未改变。</p></template></template></template></section></template>
<script setup>
import ClinicalTrainingPractice from'./ClinicalTrainingPractice.vue';import ClinicalTrainingFindings from'./ClinicalTrainingFindings.vue';import{useClinicalTrainingAssistant}from'./useClinicalTrainingAssistant';import{trainingTaskObjectives as objectives}from'@/api/ai/clinicalTrainingTasks';
const props=defineProps({active:{type:Boolean,default:true},initialReferences:{type:Object,default:null},initialObjective:{type:String,default:''},configRevision:{type:[String,Number],default:null}}),emit=defineEmits(['selection','run-change','invalidate']);const{v,session,authorized,configured,ready,configuration,select,practiceSelection,generate,history,openRun,openParts,closeParts,cancel,feedback,clear}=useClinicalTrainingAssistant(props,emit);defineExpose({openRun,clear});
</script><style scoped>section{display:grid;gap:12px}table{width:100%}label{display:grid;gap:8px}</style>
